kNeigh = input(7, "K Neighbours", 1, 15, 1)
featLook = input(20, "Feature Lookback", 5, 40, 1)
searchHist = input(200, "Search History", 30, 500, 5)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagThresh = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

rCur = (close - open) / (open + 0.000000001)
hCur = (high - low) / (close + 0.000000001)

var rHist = array(0)
var hHist = array(0)
var cHist = array(0)

array.push(rHist, rCur)
array.push(hHist, hCur)
array.push(cHist, close)

numBars = array.size(cHist)

voteM = 0.0
gnorm = 0.5
upVotes = 0
dnVotes = 0

if numBars > featLook + kNeigh + 2 {
    bestD = array()
    bestT = array()
    bi = 0
    while bi < kNeigh {
        array.push(bestD, 999999.0)
        array.push(bestT, 0)
        bi := bi + 1
    }
    hi = numBars - 1 - searchHist
    if hi < featLook { hi := featLook }
    lo = numBars - 2
    t = hi
    while t <= lo {
        dd = 0.0
        f = 0
        while f < featLook {
            cr = rHist[numBars - 1 - f]
            pr = rHist[t - f]
            ch = hHist[numBars - 1 - f]
            ph = hHist[t - f]
            dr = cr - pr
            dh = ch - ph
            dd := dd + dr * dr + dh * dh
            f := f + 1
        }
        dd := sqrt(dd)
        insIdx = 0 - 1
        m = 0
        while m < kNeigh {
            if dd < bestD[m] {
                insIdx := m
                m := kNeigh
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = kNeigh - 1
            while m > insIdx {
                array.set(bestD, m, bestD[m - 1])
                array.set(bestT, m, bestT[m - 1])
                m := m - 1
            }
            lbl = 0 - 1
            if cHist[t + 1] > cHist[t] { lbl := 1 }
            array.set(bestD, insIdx, dd)
            array.set(bestT, insIdx, lbl)
        }
        t := t + 1
    }
    up = 0
    dn = 0
    md = 0.0
    m = 0
    while m < kNeigh {
        if bestD[m] < 999999.0 {
            md := md + bestD[m]
            if bestT[m] == 1 { up := up + 1 }
            else { dn := dn + 1 }
        }
        m := m + 1
    }
    upVotes := up
    dnVotes := dn
    tot = up + dn
    if tot > 0 {
        voteM := (up - dn) / tot
        md := md / tot
        sd = 0.0
        m = 0
        while m < kNeigh {
            if bestD[m] < 999999.0 {
                dev = bestD[m] - md
                sd := sd + dev * dev
            }
            m := m + 1
        }
        sd := sqrt(sd / tot)
        g = sd / (md + 0.0001)
        gnorm := g / (g + 1.0)
    }
}

buyCond = voteM > marginThresh and gnorm < disagThresh
sellCond = voteM < (0 - marginThresh) and gnorm < disagThresh

buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

warm = bar_index >= featLook + 10
buyFire = buySig and warm
sellFire = sellSig and warm

if buyFire {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellFire {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

bandW = gnorm * 0.5
upperBand = voteM + bandW
lowerBand = voteM - bandW
crisp = 1.0 - gnorm
upPrism = 0.0
dnPrism = 0.0
if voteM > 0 {
    upPrism := voteM * (crisp + 0.15)
}
if voteM < 0 {
    dnPrism := (0 - voteM) * (crisp + 0.15)
}

plot(voteM, "Vote Margin M", "#22cc88", 2, "separate")
plot(upperBand, "Disagree Upper", "rgba(255,68,170,0.7)", 1, "separate")
plot(lowerBand, "Disagree Lower", "rgba(255,68,170,0.7)", 1, "separate")
fill(upperBand, lowerBand, "rgba(255,68,170,0.08)")
plot(gnorm, "Disagreement Gnorm", "#ff44aa", 1, "separate")

plot3d(upPrism, "Consensus Up Prism", "bars3d", "#22cc88", "separate", 0)
plot3d(dnPrism, "Consensus Down Prism", "bars3d", "#ff44aa", "separate", 1)
plot3d(gnorm, "Disagreement Sheath", "ribbon", "#b48cff", "separate", 2)

if buyFire {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellFire {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 1, "separate")
}

// Visible Session Volume Value Model
// Session volume profile with POC + value area expansion, breakout signals.

numRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
lookback = input(120, "Session Lookback Bars", 40, 300, 10)
showHist = input(true, "Show Profile Histogram")
showBox = input(true, "Show Value Area Box")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window range ───
hh = highest(high, lookback)
ll = lowest(low, lookback)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
if rng < close * 0.0005 {
    rng := close * 0.0005
}

// ─── Fresh volume-at-price bins rebuilt every bar ───
binVol = array()
i = 0
while i < numRows {
    array.push(binVol, 0.0)
    i := i + 1
}
j = 0
while j < lookback {
    typ = (high[j] + low[j] + close[j]) / 3
    vv = volume[j]
    bi = floor((typ - ll) / rng * numRows)
    if bi < 0 {
        bi := 0
    }
    if bi > numRows - 1 {
        bi := numRows - 1
    }
    array.set(binVol, bi, array.get(binVol, bi) + vv)
    j := j + 1
}

// ─── Point of control ───
pocBin = 0
pocVal = array.get(binVol, 0)
k = 1
while k < numRows {
    v = array.get(binVol, k)
    if v > pocVal {
        pocVal := v
        pocBin := k
    }
    k := k + 1
}
totalVol = array.sum(binVol)
pocPrice = ll + (pocBin + 0.5) / numRows * rng
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVal / totalVol
}

// ─── Value area expansion from POC ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < numRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < numRows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < numRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vaHighPrice = ll + (vaHigh + 1) / numRows * rng
vaLowPrice = ll + vaLow / numRows * rng
vaMid = (vaHighPrice + vaLowPrice) / 2
avgBinVol = totalVol / numRows
terrainSurf = vaMid + (pocVal - avgBinVol) / avgBinVol * rng * 0.5 + (close - vaMid) * 0.05
insideVA = close >= vaLowPrice and close <= vaHighPrice
insidePrev = close[1] >= vaLowPrice[1] and close[1] <= vaHighPrice[1]

// ─── Signals: price leaving value ───
buySig = insidePrev and close > vaHighPrice
sellSig = insidePrev and close < vaLowPrice
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
    model.longEntry("Buy")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d")
    model.shortEntry("Sell")
}

// ─── 2D drawings: value box + histogram + level tags ───
if showBox {
    box.new(bar_index - lookback, vaHighPrice, bar_index, vaLowPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "vabox")
}
if showHist {
    b = 0
    while b < numRows {
        bv = array.get(binVol, b)
        blen = 0.0
        if pocVal > 0 {
            blen := bv / pocVal * 20
        }
        btop = ll + (b + 1) / numRows * rng
        bbot = ll + b / numRows * rng
        bcol = "rgba(120,140,180,0.35)"
        if b == pocBin {
            bcol := "#ffd43b"
        }
        if b >= vaLow and b <= vaHigh {
            bcol := "rgba(34,204,136,0.45)"
        }
        if b == pocBin {
            bcol := "#ffd43b"
        }
        box.new(bar_index - blen, btop, bar_index, bbot, bcol, bcol, 1, "prof")
        b := b + 1
    }
}
text.new(bar_index, pocPrice, "POC", "#ffd43b", 12, "tagPOC")
text.new(bar_index, vaHighPrice, "VAH", "#22cc88", 12, "tagVAH")
text.new(bar_index, vaLowPrice, "VAL", "#ff4477", 12, "tagVAL")

// ─── 2D twins (render when 3D off) ───
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vaHighPrice, "VAH", "#22cc88", 1, "stepline")
plot(vaLowPrice, "VAL", "#ff4477", 1, "stepline")
fill("VAH", "VAL", "rgba(34,204,136,0.08)")

// ─── 3D: value terrain + POC rail + value rails ───
plot3d(terrainSurf, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vaHighPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain assignment recomputed every bar.
// FIX 2: close[-1] peeked one bar into the future — changed to close so buySig uses current close only.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine signature — changed to OakScript (bar_index, price, title, style, color) with quoted strings.
// FIX 4: oscillator RSI forced into pane "3d" renders as spiky forest over candles — moved to pane "separate" plus 2D twin.
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", 1.0, "separate")
}
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowBase = input(100, "Flow PSI Base", 0, 300, 1)
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
ringCount = input(5, "Ring Count", 1, 10, 1)
ringSpeed = input(1.0, "Ring Expansion Speed", 0.1, 5.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = flowBase + (close - open) * 8 + (high - low) * 3
spin_speed = flow_psi * spinFactor
isOver = flow_psi > critThresh
trig = flow_psi > critThresh and flow_psi[1] <= critThresh
clearSig = flow_psi <= critThresh and flow_psi[1] > critThresh
discVal = flow_psi
shockVal = flow_psi + ringRad * 4 + (high - low) * 2
discSize = 1.2 * markerSize

var rotY = 0.0
var ringRad = 0.0

if isOver {
    rotY := rotY[1]
} else {
    rotY := rotY[1] + spin_speed
}

if trig {
    ringRad := 1.0
} else {
    if isOver {
        ringRad := ringRad[1] + ringSpeed
    } else {
        ringRad := 0.0
    }
}

buySig = trig
sellSig = clearSig

if buySig {
    plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}

if sellSig {
    plotshape(bar_index, low, "Pressure Clear", "triangleup", "#22cc88")
}

if isOver {
    plotshape_3d(bar_index, flow_psi, "Valve Disc", "torus", "#22aaff", discSize, 0, "separate", 90, rotY, 0)
}

if isOver {
    for i = 0 to ringCount {
        ringSize = 0.6 + i * 0.35 + ringRad * 0.08
        plotshape_3d(bar_index, flow_psi, "Shock Ring", "torus", "#ff5533", ringSize, 1, "separate", 90, 0, 0)
    }
}

if buySig {
    label3d(bar_index, flow_psi, "OVERPRESSURE", "#ff4477", 2, 2, "separate")
}

plot(flow_psi, "Flow PSI", "#22aaff", 2, "separate")
hline(critThresh, "#ff4477", "separate")
plot3d(discVal, "Valve Disc", "torus", "#22aaff", "separate", 0)
plot3d(shockVal, "Shock Front", "trail", "#ff5533", "separate", 1)
